export type Groups = ReturnType<typeof createGroups>;

export const errorTags = [
  "CommandNotFoundError",
  "ConflictError",
  "ForbiddenError",
  "InvalidCursorError",
  "InvalidRequestError",
  "MessageNotFoundError",
  "MemoryNotFoundError",
  "RequestNotFoundError",
  "RewindConflictError",
  "ServiceUnavailableError",
  "BudgetExceededError",
  "SessionBusyError",
  "SessionNotFoundError",
  "UnauthorizedError",
  "UnknownError",
] as const;

export type ErrorTag = (typeof errorTags)[number];

/** An error carrying a server `_tag`, such as `CyberApiError`. */
export interface TaggedError<Tag extends string = string> {
  readonly tag: Tag;
  readonly status: number;
  readonly body: S.ErrorBody;
}

function hasTag(err: unknown, tag: string): boolean {
  return typeof err === "object" && err !== null && (err as { tag?: unknown }).tag === tag;
}

export function isCommandNotFoundError(err: unknown): err is TaggedError<"CommandNotFoundError"> {
  return hasTag(err, "CommandNotFoundError");
}

export function isConflictError(err: unknown): err is TaggedError<"ConflictError"> {
  return hasTag(err, "ConflictError");
}

export function isForbiddenError(err: unknown): err is TaggedError<"ForbiddenError"> {
  return hasTag(err, "ForbiddenError");
}

export function isInvalidCursorError(err: unknown): err is TaggedError<"InvalidCursorError"> {
  return hasTag(err, "InvalidCursorError");
}

export function isInvalidRequestError(err: unknown): err is TaggedError<"InvalidRequestError"> {
  return hasTag(err, "InvalidRequestError");
}

export function isMessageNotFoundError(err: unknown): err is TaggedError<"MessageNotFoundError"> {
  return hasTag(err, "MessageNotFoundError");
}

export function isMemoryNotFoundError(err: unknown): err is TaggedError<"MemoryNotFoundError"> {
  return hasTag(err, "MemoryNotFoundError");
}

export function isRequestNotFoundError(err: unknown): err is TaggedError<"RequestNotFoundError"> {
  return hasTag(err, "RequestNotFoundError");
}

export function isRewindConflictError(err: unknown): err is TaggedError<"RewindConflictError"> {
  return hasTag(err, "RewindConflictError");
}

export function isServiceUnavailableError(err: unknown): err is TaggedError<"ServiceUnavailableError"> {
  return hasTag(err, "ServiceUnavailableError");
}

export function isBudgetExceededError(err: unknown): err is TaggedError<"BudgetExceededError"> {
  return hasTag(err, "BudgetExceededError");
}

export function isSessionBusyError(err: unknown): err is TaggedError<"SessionBusyError"> {
  return hasTag(err, "SessionBusyError");
}

export function isSessionNotFoundError(err: unknown): err is TaggedError<"SessionNotFoundError"> {
  return hasTag(err, "SessionNotFoundError");
}

export function isUnauthorizedError(err: unknown): err is TaggedError<"UnauthorizedError"> {
  return hasTag(err, "UnauthorizedError");
}

export function isUnknownError(err: unknown): err is TaggedError<"UnknownError"> {
  return hasTag(err, "UnknownError");
}
